//! Key → [`Action`] mapping: the single source of truth for shortcuts.
//!
//! Every configurable action has a stable identifier (`hosts.connect`,
//! `prefix.files`…) in [`BINDINGS`], with its default keys. At startup,
//! `settings.toml` (`[keymap.tui]`, action → keys) replaces the defaults of
//! the actions it names ([`Keymap::with_overrides`]); invalid entries
//! (unknown action, unreadable key, reserved key, conflict in the same
//! context) are ignored and reported. The `?` overlay ([`help`]), the
//! status bar and `docs/KEYBINDINGS.md` (generated by [`crate::keydoc`])
//! all read from here, so what is shown is what works.
//!
//! Panels (files, tunnels, keys, snippets, edit, debug) and dialogs take
//! every key themselves: their keys are fixed and documented in
//! [`crate::keydoc`].

use std::collections::BTreeMap;

use crossterm::event::{KeyCode, KeyEvent, KeyEventKind, KeyModifiers};

use crate::action::Action;
use crate::app::{Focus, Overlay};
use crate::panes::{Dir, Split};

/// Where a binding applies.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum Context {
    /// The host list (and any view that is not a panel or a terminal).
    Hosts,
    /// The key after `Ctrl-Space`, from every view.
    Prefix,
    /// A terminal tab (every other key goes to the remote program).
    Terminal,
}

#[cfg(test)]
impl Context {
    pub(crate) fn id(self) -> &'static str {
        match self {
            Self::Hosts => "hosts",
            Self::Prefix => "prefix",
            Self::Terminal => "terminal",
        }
    }
}

/// One configurable action.
#[derive(Debug)]
pub(crate) struct Binding {
    /// Stable identifier, used in `settings.toml`.
    pub(crate) id: &'static str,
    pub(crate) context: Context,
    /// Default keys, in [`KeySpec::parse`] syntax.
    pub(crate) keys: &'static [&'static str],
    /// Short English label (status bar).
    pub(crate) label: &'static str,
    /// French description (`docs/KEYBINDINGS.md`).
    pub(crate) doc: &'static str,
    action: fn() -> Action,
}

macro_rules! bind {
    ($id:literal, $ctx:ident, [$($key:literal),+], $label:literal, $doc:literal, $action:expr) => {
        Binding {
            id: $id,
            context: Context::$ctx,
            keys: &[$($key),+],
            label: $label,
            doc: $doc,
            action: || $action,
        }
    };
}

