// ── key syntax ──────────────────────────────────────────────────────────

/// A key as written in `settings.toml`: `j`, `G`, `*`, `enter`, `ctrl-k`,
/// `alt-x`, `shift-pgup`, `f5`… A letter's case is the key (`G` is
/// Shift-g); named keys and modifiers ignore case.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) struct KeySpec {
    code: KeyCode,
    ctrl: bool,
    alt: bool,
    /// Only for named keys (a character carries its own shift).
    shift: bool,
}

impl KeySpec {
    pub(crate) fn parse(text: &str) -> Option<Self> {
        let text = text.trim();
        let mut spec = Self {
            code: KeyCode::Null,
            ctrl: false,
            alt: false,
            shift: false,
        };
        let mut rest = text;
        // Modifiers: `ctrl-`, `ctrl+`, `alt-`, `shift-` (any case).
        loop {
            if rest.chars().count() <= 1 {
                break;
            }
            let lower = rest.to_ascii_lowercase();
            let modifier = ["ctrl", "control", "alt", "meta", "shift"]
                .into_iter()
                .find(|m| {
                    lower.starts_with(m)
                        && matches!(lower.as_bytes().get(m.len()), Some(b'-' | b'+'))
                        && lower.len() > m.len() + 1
                });
            let Some(modifier) = modifier else { break };
            match modifier {
                "ctrl" | "control" => spec.ctrl = true,
                "alt" | "meta" => spec.alt = true,
                _ => spec.shift = true,
            }
            rest = rest.get(modifier.len() + 1..)?;
        }
        let mut chars = rest.chars();
        if let (Some(c), None) = (chars.next(), chars.next()) {
            if spec.shift || c.is_control() {
                // `shift-g` is written `G`.
                return None;
            }
            spec.code = KeyCode::Char(if spec.ctrl { c.to_ascii_lowercase() } else { c });
            return Some(spec);
        }
        let lower = rest.to_ascii_lowercase();
        spec.code = match lower.as_str() {
            "enter" | "return" => KeyCode::Enter,
            "esc" | "escape" => KeyCode::Esc,
            "tab" if spec.shift => {
                spec.shift = false;
                KeyCode::BackTab
            }
            "tab" => KeyCode::Tab,
            "backtab" => KeyCode::BackTab,
            "space" => KeyCode::Char(' '),
            "backspace" | "bksp" => KeyCode::Backspace,
            "delete" | "del" => KeyCode::Delete,
            "insert" | "ins" => KeyCode::Insert,
            "home" => KeyCode::Home,
            "end" => KeyCode::End,
            "pgup" | "pageup" => KeyCode::PageUp,
            "pgdn" | "pagedown" => KeyCode::PageDown,
            "up" => KeyCode::Up,
            "down" => KeyCode::Down,
            "left" => KeyCode::Left,
            "right" => KeyCode::Right,
            name => {
                let n: u8 = name.strip_prefix('f')?.parse().ok()?;
                if !(1..=12).contains(&n) {
                    return None;
                }
                KeyCode::F(n)
            }
        };
        if spec.shift && matches!(spec.code, KeyCode::Char(_)) {
            return None;
        }
        Some(spec)
    }

    pub(crate) fn matches(self, key: &KeyEvent) -> bool {
        let m = key.modifiers;
        if m.contains(KeyModifiers::CONTROL) != self.ctrl
            || m.contains(KeyModifiers::ALT) != self.alt
        {
            return false;
        }
        match (self.code, key.code) {
            // A character carries its own shift (`G`, `*`, `?`).
            (KeyCode::Char(a), KeyCode::Char(b)) => a == b,
            (KeyCode::BackTab, KeyCode::BackTab) => true,
            (a, b) => a == b && m.contains(KeyModifiers::SHIFT) == self.shift,
        }
    }

    /// Never rebindable: they quit, cancel or open the prefix everywhere.
    fn reserved(self) -> bool {
        let plain = !self.ctrl && !self.alt && !self.shift;
        match self.code {
            KeyCode::Esc => true,
            KeyCode::Char('c' | ' ' | '@') if self.ctrl && !self.alt => true,
            KeyCode::Char('1'..='9') => plain,
            _ => false,
        }
    }

    /// `j`, `G`, `↵`, `Ctrl-K`, `Shift-PgUp`, `F5`.
    pub(crate) fn display(self) -> String {
        let name = match self.code {
            KeyCode::Char(' ') => "Space".to_owned(),
            KeyCode::Char(c) if self.ctrl => c.to_uppercase().to_string(),
            KeyCode::Char(c) => c.to_string(),
            KeyCode::Enter => "↵".to_owned(),
            KeyCode::Esc => "Esc".to_owned(),
            KeyCode::Tab => "Tab".to_owned(),
            KeyCode::BackTab => "Shift-Tab".to_owned(),
            KeyCode::Backspace => "Bksp".to_owned(),
            KeyCode::Delete => "Del".to_owned(),
            KeyCode::Insert => "Ins".to_owned(),
            KeyCode::Home => "Home".to_owned(),
            KeyCode::End => "End".to_owned(),
            KeyCode::PageUp => "PgUp".to_owned(),
            KeyCode::PageDown => "PgDn".to_owned(),
            KeyCode::Up => "↑".to_owned(),
            KeyCode::Down => "↓".to_owned(),
            KeyCode::Left => "←".to_owned(),
            KeyCode::Right => "→".to_owned(),
            KeyCode::F(n) => format!("F{n}"),
            _ => "?".to_owned(),
        };
        let mut out = String::new();
        if self.ctrl {
            out.push_str("Ctrl-");
        }
        if self.alt {
            out.push_str("Alt-");
        }
        if self.shift {
            out.push_str("Shift-");
        }
        out.push_str(&name);
        out
    }
}

// ── the effective keymap ────────────────────────────────────────────────

/// Effective keys of every [`BINDINGS`] entry (same order).
#[derive(Debug, Clone)]
pub(crate) struct Keymap {
    keys: Vec<Vec<KeySpec>>,
}

/// Most keys one action takes from `settings.toml`.
const MAX_KEYS_PER_ACTION: usize = 4;

impl Default for Keymap {
    fn default() -> Self {
        Self::defaults()
    }
}

impl Keymap {
    pub(crate) fn defaults() -> Self {
        Self {
            keys: BINDINGS
                .iter()
                .map(|b| b.keys.iter().filter_map(|k| KeySpec::parse(k)).collect())
                .collect(),
        }
    }

    /// The defaults with `overrides` (action id → keys separated by
    /// spaces) applied; the second value lists the ignored entries, each
    /// with its reason.
    pub(crate) fn with_overrides(overrides: &BTreeMap<String, String>) -> (Self, Vec<String>) {
        let mut map = Self::defaults();
        let mut ignored = Vec::new();
        // Index → (keys, entry text) of the overrides that parse.
        let mut applied: BTreeMap<usize, (Vec<KeySpec>, String)> = BTreeMap::new();
        for (id, value) in overrides {
            let shown_id = crate::ui::fmt::truncate(id, 32);
            let shown = format!("{shown_id} = {}", crate::ui::fmt::truncate(value, 24));
            let Some(index) = BINDINGS.iter().position(|b| b.id == id) else {
                ignored.push(format!("{shown_id} (unknown action)"));
                continue;
            };
            let words: Vec<&str> = value.split_whitespace().collect();
            if words.is_empty() || words.len() > MAX_KEYS_PER_ACTION {
                ignored.push(format!("{shown} (1 to 4 keys)"));
                continue;
            }
            let Some(mut keys) = words
                .iter()
                .map(|w| KeySpec::parse(w))
                .collect::<Option<Vec<_>>>()
            else {
                ignored.push(format!("{shown} (unreadable key)"));
                continue;
            };
            keys.dedup();
            if keys.iter().any(|k| k.reserved()) {
                ignored.push(format!("{shown} (reserved key)"));
                continue;
            }
            let context = BINDINGS.get(index).map(|b| b.context);
            // In a terminal, a plain key belongs to the remote program.
            if context == Some(Context::Terminal)
                && keys.iter().any(|k| !(k.ctrl || k.alt || k.shift))
            {
                ignored.push(format!("{shown} (a terminal key needs Ctrl, Alt or Shift)"));
                continue;
            }
            if let Some(slot) = map.keys.get_mut(index) {
                slot.clone_from(&keys);
            }
            applied.insert(index, (keys, shown));
        }
        // Conflicts: an override that shares a key with another action of
        // its context is dropped (back to its defaults), until none is left.
        loop {
            let mut dropped = None;
            'search: for &index in applied.keys() {
                let Some(binding) = BINDINGS.get(index) else {
                    continue;
                };
                let mine = map.keys.get(index).cloned().unwrap_or_default();
                for (other, b) in BINDINGS.iter().enumerate() {
                    if other == index || b.context != binding.context {
                        continue;
                    }
                    let theirs = map.keys.get(other).map(Vec::as_slice).unwrap_or_default();
                    if mine.iter().any(|k| theirs.contains(k)) {
                        dropped = Some((index, other));
                        break 'search;
                    }
                }
            }
            let Some((index, other)) = dropped else { break };
            // Two overrides on one key: neither wins.
            for (loser, with) in [(index, other), (other, index)] {
                let with = BINDINGS.get(with).map_or("", |b| b.id);
                if let Some((_, shown)) = applied.remove(&loser) {
                    ignored.push(format!("{shown} (conflicts with {with})"));
                    if let (Some(slot), Some(binding)) =
                        (map.keys.get_mut(loser), BINDINGS.get(loser))
                    {
                        *slot = binding
                            .keys
                            .iter()
                            .filter_map(|k| KeySpec::parse(k))
                            .collect();
                    }
                }
            }
        }
        (map, ignored)
    }

    pub(crate) fn keys(&self, id: &str) -> &[KeySpec] {
        BINDINGS
            .iter()
            .position(|b| b.id == id)
            .and_then(|i| self.keys.get(i))
            .map(Vec::as_slice)
            .unwrap_or_default()
    }

    /// The first `max` keys of `id`, space-separated (`/ Ctrl-K`).
    pub(crate) fn shown(&self, id: &str, max: usize) -> String {
        self.keys(id)
            .iter()
            .take(max)
            .map(|k| k.display())
            .collect::<Vec<_>>()
            .join(" ")
    }

    /// The first key of each of `ids`, run together when each is one
    /// character after a shared modifier (`←↓↑→`, `Shift-←↓↑→`), else
    /// separated by spaces.
    pub(crate) fn joined(&self, ids: &[&str]) -> String {
        let keys: Vec<String> = ids
            .iter()
            .filter_map(|id| self.keys(id).first().map(|k| k.display()))
            .collect();
        let Some(first) = keys.first() else {
            return String::new();
        };
        // The longest modifier prefix (`Shift-`, `Ctrl-Alt-`) all share.
        let shared = first
            .match_indices('-')
            .map(|(i, _)| i + 1)
            .rev()
            .find(|&end| {
                keys.iter()
                    .all(|k| k.get(..end) == first.get(..end) && k.chars().count() == end + 1)
            })
            .unwrap_or(0);
        let tails: Option<Vec<&str>> = keys.iter().map(|k| k.get(shared..)).collect();
        match tails {
            Some(tails) if tails.iter().all(|t| t.chars().count() == 1) => {
                format!(
                    "{}{}",
                    first.get(..shared).unwrap_or_default(),
                    tails.concat()
                )
            }
            _ => keys.join(" "),
        }
    }

    /// Status-bar hint: first key and label of `id` (`None` if unbound).
    pub(crate) fn hint(&self, id: &str) -> Option<(String, &'static str)> {
        let label = BINDINGS.iter().find(|b| b.id == id)?.label;
        let key = self.keys(id).first()?.display();
        Some((key, label))
    }

    fn lookup(&self, context: Context, key: &KeyEvent) -> Option<Action> {
        self.binding(context, key).map(|b| (b.action)())
    }

    fn binding(&self, context: Context, key: &KeyEvent) -> Option<&'static Binding> {
        BINDINGS
            .iter()
            .zip(&self.keys)
            .find(|(b, keys)| b.context == context && keys.iter().any(|k| k.matches(key)))
            .map(|(b, _)| b)
    }
}

