/// A section of the `?` overlay, with the effective keys.
#[derive(Debug, Clone)]
pub(crate) struct HelpSection {
    pub(crate) title: &'static str,
    /// Page shown when the whole help does not fit at once.
    pub(crate) page: usize,
    pub(crate) rows: Vec<(String, &'static str)>,
}

pub(crate) fn help(keymap: &Keymap) -> Vec<HelpSection> {
    HELP.iter()
        .map(|(title, page, rows)| HelpSection {
            title,
            page: *page,
            rows: rows
                .iter()
                .map(|(keys, label)| {
                    let cells: Vec<String> = keys
                        .iter()
                        .map(|k| match k {
                            Id(id, n) => keymap.shown(id, *n),
                            Joined(ids) => keymap.joined(ids),
                            Fixed(text) => (*text).to_owned(),
                        })
                        .filter(|c| !c.is_empty())
                        .collect();
                    (cells.join(" · "), *label)
                })
                .collect(),
        })
        .collect()
}

// ── dispatch ────────────────────────────────────────────────────────────

/// What the dispatcher needs to know about the app.
#[derive(Debug, Clone, Copy)]
pub(crate) struct KeyContext<'a> {
    pub(crate) focus: Focus,
    pub(crate) overlay: Option<Overlay>,
    pub(crate) dialog_open: bool,
    pub(crate) prefix: bool,
    /// The host list picks the host of a new pane (`Ctrl-Space S`).
    pub(crate) picking: bool,
    pub(crate) keymap: &'a Keymap,
}

/// While picking a pane's host, the list only moves, searches and chooses.
const PICKING_KEYS: &[&str] = &[
    "hosts.down",
    "hosts.up",
    "hosts.first",
    "hosts.last",
    "hosts.search",
    "hosts.clear_search",
    "hosts.connect",
    "hosts.help",
];

pub(crate) fn map_key(key: KeyEvent, cx: KeyContext<'_>) -> Option<Action> {
    let KeyContext {
        focus,
        overlay,
        dialog_open,
        prefix,
        picking,
        keymap,
    } = cx;
    let overlay_open = overlay.is_some();
    if key.kind == KeyEventKind::Release {
        return None;
    }
    let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
    // Dialogs grab every key (Ctrl-C cancels instead of quitting).
    if dialog_open {
        if ctrl && key.code == KeyCode::Char('c') {
            return Some(Action::DialogKey(KeyEvent::new(
                KeyCode::Esc,
                KeyModifiers::NONE,
            )));
        }
        return Some(Action::DialogKey(key));
    }
    if key.kind != KeyEventKind::Press && focus != Focus::Terminal {
        return None;
    }
    let is_prefix_key = ctrl && matches!(key.code, KeyCode::Char(' ' | '@'));
    if overlay == Some(Overlay::Help)
        && let Some(action) = help_key(key)
    {
        return Some(action);
    }
    if let Some(action) = panel_key(key, overlay, ctrl) {
        return Some(action);
    }
    // The prefix works from every view, so tab commands are the same everywhere.
    if prefix {
        return Some(prefix_command(key, is_prefix_key, focus, keymap));
    }
    if focus == Focus::Files && !overlay_open {
        return Some(match key.code {
            _ if is_prefix_key => Action::Prefix,
            // Ctrl-C leaves the explorer rather than quitting Portico.
            KeyCode::Char('c') if ctrl => {
                Action::FilesKey(KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE))
            }
            KeyCode::Char('?') => Action::ToggleHelp,
            _ => Action::FilesKey(key),
        });
    }
    if focus == Focus::Terminal {
        if overlay_open {
            return Some(Action::CloseOverlay);
        }
        if is_prefix_key {
            return Some(Action::Prefix);
        }
        return Some(
            keymap
                .lookup(Context::Terminal, &key)
                .unwrap_or(Action::TerminalKey(key)),
        );
    }
    if ctrl && key.code == KeyCode::Char('c') {
        // Picking a pane's host: Ctrl-C cancels the pick, not Portico.
        return Some(if picking && !overlay_open {
            Action::CancelPanePick
        } else {
            Action::Quit
        });
    }
    if overlay_open {
        return match key.code {
            KeyCode::Esc | KeyCode::Char('?' | 'q') => Some(Action::CloseOverlay),
            _ => None,
        };
    }
    match focus {
        // Text entry: fixed keys, every other character is typed.
        Focus::Search => match key.code {
            KeyCode::Esc if picking => Some(Action::CancelPanePick),
            KeyCode::Esc => Some(Action::BlurSearch),
            KeyCode::Enter => Some(Action::Connect),
            KeyCode::Down => Some(Action::SelectNext),
            KeyCode::Up => Some(Action::SelectPrev),
            KeyCode::Backspace => Some(Action::SearchBackspace),
            KeyCode::Char('u') if ctrl => Some(Action::SearchClear),
            KeyCode::Char('n') if ctrl => Some(Action::SelectNext),
            KeyCode::Char('p') if ctrl => Some(Action::SelectPrev),
            KeyCode::Char(c) if !ctrl => Some(Action::SearchInput(c)),
            _ => None,
        },
        Focus::Hosts if picking => pick_key(key, is_prefix_key, keymap),
        Focus::Hosts | Focus::Terminal | Focus::Files => match key.code {
            _ if is_prefix_key => Some(Action::Prefix),
            KeyCode::Esc => Some(Action::SearchClear),
            KeyCode::Char(c @ '1'..='9') if !ctrl => {
                Some(Action::GoTab(usize::from(c as u8 - b'1')))
            }
            _ => keymap.lookup(Context::Hosts, &key),
        },
    }
}

/// The host list while it picks a new pane's host: `Esc` cancels, the
/// list only moves, searches and chooses (`↵`).
fn pick_key(key: KeyEvent, is_prefix_key: bool, keymap: &Keymap) -> Option<Action> {
    let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
    match key.code {
        _ if is_prefix_key => Some(Action::Prefix),
        KeyCode::Esc => Some(Action::CancelPanePick),
        KeyCode::Char(c @ '1'..='9') if !ctrl => Some(Action::GoTab(usize::from(c as u8 - b'1'))),
        _ => keymap
            .binding(Context::Hosts, &key)
            .filter(|b| PICKING_KEYS.contains(&b.id))
            .map(|b| (b.action)()),
    }
}

/// Keys of the help overlay: `Tab` / `←` `→` turn the page, `Esc` / `?` /
/// `q` / `Ctrl-C` close it; the rest is ignored.
pub(crate) fn help_key(key: KeyEvent) -> Option<Action> {
    let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
    match key.code {
        KeyCode::Char('c') if ctrl => Some(Action::CloseHelp),
        KeyCode::Tab | KeyCode::BackTab | KeyCode::Left | KeyCode::Right => Some(Action::HelpPage),
        KeyCode::Esc | KeyCode::Char('?' | 'q') => Some(Action::CloseHelp),
        _ => None,
    }
}

/// Panels take every key (they hold forms and lists); `Ctrl-C` closes them.
fn panel_key(key: KeyEvent, overlay: Option<Overlay>, ctrl: bool) -> Option<Action> {
    let wrap: fn(KeyEvent) -> Action = match overlay? {
        Overlay::Tunnels => Action::TunnelsKey,
        Overlay::Keys => Action::KeysKey,
        Overlay::Snippets => Action::SnippetsKey,
        Overlay::Edit => Action::EditKey,
        Overlay::Debug => Action::DebugKey,
        Overlay::Help => return None,
    };
    if ctrl && key.code == KeyCode::Char('c') {
        return Some(Action::CloseOverlay);
    }
    Some(wrap(key))
}

fn prefix_command(key: KeyEvent, is_prefix_key: bool, focus: Focus, keymap: &Keymap) -> Action {
    if is_prefix_key {
        // Ctrl-Space twice: deliver it to the remote program, if any.
        return if focus == Focus::Terminal {
            Action::TerminalKey(key)
        } else {
            Action::CancelPrefix
        };
    }
    let plain = !key
        .modifiers
        .intersects(KeyModifiers::CONTROL | KeyModifiers::ALT);
    match key.code {
        KeyCode::Char(c @ '1'..='9') if plain => Action::GoTab(usize::from(c as u8 - b'1')),
        _ => keymap
            .lookup(Context::Prefix, &key)
            .unwrap_or(Action::CancelPrefix),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn key(code: KeyCode, m: KeyModifiers) -> KeyEvent {
        KeyEvent::new(code, m)
    }

    fn cx(
        focus: Focus,
        overlay: Option<Overlay>,
        dialog: bool,
        prefix: bool,
        keymap: &Keymap,
    ) -> KeyContext<'_> {
        KeyContext {
            focus,
            overlay,
            dialog_open: dialog,
            prefix,
            picking: false,
            keymap,
        }
    }

    fn map(code: KeyCode, m: KeyModifiers, focus: Focus, prefix: bool) -> Option<Action> {
        map_key(
            key(code, m),
            cx(focus, None, false, prefix, &Keymap::defaults()),
        )
    }

    #[test]
    fn every_default_parses_and_ids_are_unique() {
        for (i, b) in BINDINGS.iter().enumerate() {
            assert!(
                b.id.starts_with(&format!("{}.", b.context.id())),
                "{} is not in its context",
                b.id
            );
            for k in b.keys {
                assert!(KeySpec::parse(k).is_some(), "{}: `{k}`", b.id);
            }
            assert!(
                BINDINGS.iter().skip(i + 1).all(|o| o.id != b.id),
                "duplicate {}",
                b.id
            );
        }
        let (_, ignored) = Keymap::with_overrides(&BTreeMap::new());
        assert!(ignored.is_empty());
        // No two defaults share a key in one context.
        let map = Keymap::defaults();
        for (i, a) in BINDINGS.iter().enumerate() {
            for (j, b) in BINDINGS.iter().enumerate().skip(i + 1) {
                if a.context == b.context {
                    let ka = map.keys.get(i).cloned().unwrap_or_default();
                    let kb = map.keys.get(j).cloned().unwrap_or_default();
                    assert!(!ka.iter().any(|k| kb.contains(k)), "{} / {}", a.id, b.id);
                }
            }
        }
    }

    #[test]
    fn key_syntax() {
        let p = |t: &str| KeySpec::parse(t).map(KeySpec::display);
        assert_eq!(p("j").as_deref(), Some("j"));
        assert_eq!(p("G").as_deref(), Some("G"));
        assert_eq!(p("ctrl-k").as_deref(), Some("Ctrl-K"));
        assert_eq!(p("Ctrl+K").as_deref(), Some("Ctrl-K"));
        assert_eq!(p("alt-x").as_deref(), Some("Alt-x"));
        assert_eq!(p("Enter").as_deref(), Some("↵"));
        assert_eq!(p("shift-tab").as_deref(), Some("Shift-Tab"));
        assert_eq!(p("Shift-PgUp").as_deref(), Some("Shift-PgUp"));
        assert_eq!(p("f5").as_deref(), Some("F5"));
        assert_eq!(p("space").as_deref(), Some("Space"));
        assert_eq!(p("-").as_deref(), Some("-"));
        assert_eq!(p("ctrl--").as_deref(), Some("Ctrl--"));
        for bad in ["", "ctrl-", "shift-g", "f13", "foo", "ctrl-alt", "\u{7}"] {
            assert_eq!(p(bad), None, "{bad:?}");
        }
        let star = KeySpec::parse("*").unwrap_or_else(|| unreachable!());
        assert!(star.matches(&key(KeyCode::Char('*'), KeyModifiers::SHIFT)));
        let ctrl_k = KeySpec::parse("ctrl-k").unwrap_or_else(|| unreachable!());
        assert!(ctrl_k.matches(&key(KeyCode::Char('k'), KeyModifiers::CONTROL)));
        assert!(!ctrl_k.matches(&key(KeyCode::Char('k'), KeyModifiers::NONE)));
        let up = KeySpec::parse("shift-pgup").unwrap_or_else(|| unreachable!());
        assert!(up.matches(&key(KeyCode::PageUp, KeyModifiers::SHIFT)));
        assert!(!up.matches(&key(KeyCode::PageUp, KeyModifiers::NONE)));
    }

    fn overrides(pairs: &[(&str, &str)]) -> (Keymap, Vec<String>) {
        let map: BTreeMap<String, String> = pairs
            .iter()
            .map(|(a, b)| ((*a).to_owned(), (*b).to_owned()))
            .collect();
        Keymap::with_overrides(&map)
    }

    #[test]
    fn overrides_replace_defaults() {
        let (map, ignored) = overrides(&[("hosts.files", "F"), ("prefix.debug", "L")]);
        assert!(ignored.is_empty(), "{ignored:?}");
        assert_eq!(map.shown("hosts.files", 3), "F");
        assert_eq!(map.shown("prefix.debug", 3), "L");
        let cx = cx(Focus::Hosts, None, false, false, &map);
        assert!(matches!(
            map_key(key(KeyCode::Char('F'), KeyModifiers::SHIFT), cx),
            Some(Action::OpenFiles)
        ));
        // The old key is free now.
        assert!(map_key(key(KeyCode::Char('f'), KeyModifiers::NONE), cx).is_none());
        let prefixed = KeyContext { prefix: true, ..cx };
        assert!(matches!(
            map_key(key(KeyCode::Char('L'), KeyModifiers::SHIFT), prefixed),
            Some(Action::OpenDebug)
        ));
        // Several keys, swapped keys: no conflict.
        let (map, ignored) = overrides(&[
            ("hosts.down", "n down"),
            ("hosts.files", "p"),
            ("hosts.tunnels", "f"),
        ]);
        assert!(ignored.is_empty(), "{ignored:?}");
        assert_eq!(map.shown("hosts.down", 4), "n ↓");
        assert_eq!(map.shown("hosts.tunnels", 1), "f");
    }

    #[test]
    fn invalid_overrides_are_ignored_and_listed() {
        let (map, ignored) = overrides(&[
            ("hosts.nope", "z"),
            ("hosts.files", "ctrl-alt"),
            ("hosts.tunnels", "q"),
            ("prefix.debug", "esc"),
            ("hosts.keys", "ctrl-c"),
            ("prefix.files", "ctrl-space"),
            ("hosts.snippets", "3"),
            ("terminal.scroll_up", "u"),
            ("hosts.edit", "a b c d e"),
        ]);
        assert_eq!(ignored.len(), 9, "{ignored:?}");
        for needle in [
            "hosts.nope (unknown action)",
            "hosts.files = ctrl-alt (unreadable key)",
            "hosts.tunnels = q (conflicts with hosts.quit)",
            "prefix.debug = esc (reserved key)",
            "hosts.keys = ctrl-c (reserved key)",
            "prefix.files = ctrl-space (reserved key)",
            "hosts.snippets = 3 (reserved key)",
            "terminal.scroll_up = u (a terminal key needs Ctrl, Alt or Shift)",
            "hosts.edit = a b c d e (1 to 4 keys)",
        ] {
            assert!(
                ignored.iter().any(|i| i == needle),
                "{needle} in {ignored:?}"
            );
        }
        // Everything ignored keeps its default.
        assert_eq!(map.shown("hosts.tunnels", 1), "p");
        assert_eq!(map.shown("hosts.files", 1), "f");
        assert_eq!(map.shown("prefix.debug", 1), "l");
        // Same key in another context is fine.
        let (_, ignored) = overrides(&[("prefix.debug", "q")]);
        assert!(ignored.is_empty(), "{ignored:?}");
        // Two overrides on one key: both dropped.
        let (map, ignored) = overrides(&[("hosts.files", "z"), ("hosts.tunnels", "z")]);
        assert_eq!(ignored.len(), 2, "{ignored:?}");
        assert_eq!(map.shown("hosts.files", 1), "f");
    }

    #[test]
    fn terminal_focus_sends_everything_but_the_prefix() {
        let ctrl_c = (KeyCode::Char('c'), KeyModifiers::CONTROL);
        assert!(matches!(
            map(ctrl_c.0, ctrl_c.1, Focus::Terminal, false),
            Some(Action::TerminalKey(_))
        ));
        let prefix = (KeyCode::Char(' '), KeyModifiers::CONTROL);
        assert!(matches!(
            map(prefix.0, prefix.1, Focus::Terminal, false),
            Some(Action::Prefix)
        ));
        assert!(matches!(
            map(
                KeyCode::Char('w'),
                KeyModifiers::NONE,
                Focus::Terminal,
                true
            ),
            Some(Action::CloseTab)
        ));
        assert!(matches!(
            map(prefix.0, prefix.1, Focus::Terminal, true),
            Some(Action::TerminalKey(_))
        ));
        assert!(matches!(
            map(KeyCode::PageUp, KeyModifiers::SHIFT, Focus::Terminal, false),
            Some(Action::ScrollUp)
        ));
        assert!(matches!(
            map(KeyCode::PageUp, KeyModifiers::NONE, Focus::Terminal, false),
            Some(Action::TerminalKey(_))
        ));
        assert!(matches!(
            map(
                KeyCode::Char('l'),
                KeyModifiers::NONE,
                Focus::Terminal,
                true
            ),
            Some(Action::OpenDebug)
        ));
    }

    #[test]
    fn prefix_works_from_the_host_list() {
        let prefix = (KeyCode::Char(' '), KeyModifiers::CONTROL);
        assert!(matches!(
            map(prefix.0, prefix.1, Focus::Hosts, false),
            Some(Action::Prefix)
        ));
        assert!(matches!(
            map(KeyCode::Char('2'), KeyModifiers::NONE, Focus::Hosts, true),
            Some(Action::GoTab(1))
        ));
        // Twice from the host list: nothing to forward it to.
        assert!(matches!(
            map(prefix.0, prefix.1, Focus::Hosts, true),
            Some(Action::CancelPrefix)
        ));
        assert!(matches!(
            map(KeyCode::Char('y'), KeyModifiers::NONE, Focus::Hosts, true),
            Some(Action::CancelPrefix)
        ));
    }

    #[test]
    fn host_list_keys() {
        let cases = [
            (KeyCode::Char('*'), KeyModifiers::SHIFT, "favorite"),
            (KeyCode::Char('e'), KeyModifiers::NONE, "edit"),
            (KeyCode::Char('l'), KeyModifiers::NONE, "debug"),
            (KeyCode::Char('x'), KeyModifiers::NONE, "forget"),
            (KeyCode::Char('X'), KeyModifiers::SHIFT, "clear"),
            (KeyCode::Char('3'), KeyModifiers::NONE, "tab"),
            (KeyCode::Esc, KeyModifiers::NONE, "esc"),
        ];
        for (code, m, what) in cases {
            let action = map(code, m, Focus::Hosts, false);
            let ok = match what {
                "favorite" => matches!(action, Some(Action::ToggleFavorite)),
                "edit" => matches!(action, Some(Action::EditHost)),
                "debug" => matches!(action, Some(Action::OpenDebug)),
                "forget" => matches!(action, Some(Action::ForgetRecent)),
                "clear" => matches!(action, Some(Action::AskClearRecent)),
                "tab" => matches!(action, Some(Action::GoTab(2))),
                _ => matches!(action, Some(Action::SearchClear)),
            };
            assert!(ok, "{what}: {action:?}");
        }
        // In the search field `*` is typed: it is the favorites filter.
        assert!(matches!(
            map(
                KeyCode::Char('*'),
                KeyModifiers::SHIFT,
                Focus::Search,
                false
            ),
            Some(Action::SearchInput('*'))
        ));
    }

    #[test]
    fn files_and_tunnels_capture_their_keys() {
        let keymap = Keymap::defaults();
        assert!(matches!(
            map(KeyCode::Char('d'), KeyModifiers::NONE, Focus::Files, false),
            Some(Action::FilesKey(_))
        ));
        let Some(Action::FilesKey(k)) = map(
            KeyCode::Char('c'),
            KeyModifiers::CONTROL,
            Focus::Files,
            false,
        ) else {
            panic!("ctrl-c should leave the explorer");
        };
        assert_eq!(k.code, KeyCode::Esc);
        let q = key(KeyCode::Char('q'), KeyModifiers::NONE);
        assert!(matches!(
            map_key(
                q,
                cx(Focus::Hosts, Some(Overlay::Tunnels), false, false, &keymap)
            ),
            Some(Action::TunnelsKey(_))
        ));
        assert!(matches!(
            map_key(
                q,
                cx(Focus::Hosts, Some(Overlay::Debug), false, false, &keymap)
            ),
            Some(Action::DebugKey(_))
        ));
        assert!(matches!(
            map_key(
                q,
                cx(Focus::Hosts, Some(Overlay::Edit), false, false, &keymap)
            ),
            Some(Action::EditKey(_))
        ));
        assert!(matches!(
            map(
                KeyCode::Char('f'),
                KeyModifiers::NONE,
                Focus::Terminal,
                true
            ),
            Some(Action::OpenFiles)
        ));
    }

    #[test]
    fn dialogs_capture_keys_and_ctrl_c_cancels() {
        let keymap = Keymap::defaults();
        let ctrl_c = key(KeyCode::Char('c'), KeyModifiers::CONTROL);
        let Some(Action::DialogKey(k)) =
            map_key(ctrl_c, cx(Focus::Hosts, None, true, false, &keymap))
        else {
            panic!("dialog should capture");
        };
        assert_eq!(k.code, KeyCode::Esc);
    }

    #[test]
    fn help_shows_effective_keys() {
        let (map, _) = overrides(&[("hosts.files", "F"), ("hosts.debug", "L")]);
        let sections = help(&map);
        let hosts = sections.first().map(|s| s.rows.clone()).unwrap_or_default();
        assert!(
            hosts.contains(&("F · p".to_owned(), "Files · tunnels")),
            "{hosts:?}"
        );
        assert!(
            hosts.contains(&("e · *".to_owned(), "Edit · favorite")),
            "{hosts:?}"
        );
        assert!(
            hosts.contains(&("L".to_owned(), "Session logs")),
            "{hosts:?}"
        );
        let defaults = help(&Keymap::defaults());
        // The logs panel and the edit form have their own sections.
        let titles: Vec<&str> = defaults.iter().map(|s| s.title).collect();
        assert!(titles.contains(&"Session logs") && titles.contains(&"Edit host"));
        // Never "star": the word is "favorite" everywhere.
        assert!(
            defaults
                .iter()
                .flat_map(|s| s.rows.iter())
                .all(|(_, label)| !label.contains("star"))
        );
        let hosts = defaults.first().map(|s| s.rows.clone()).unwrap_or_default();
        assert!(hosts.contains(&("/ Ctrl-K".to_owned(), "Search #tag * @grp")));
        assert!(hosts.contains(&("1-9 · ] · [".to_owned(), "Tab · next · prev")));
        for section in &defaults {
            for (keys, label) in &section.rows {
                assert!(keys.chars().count() <= 12, "{keys}");
                assert!(label.chars().count() <= 19, "{label}");
            }
        }
        let panes = defaults
            .iter()
            .find(|s| s.title == "Panes (Ctrl-Space)")
            .map(|s| s.rows.clone())
            .unwrap_or_default();
        assert!(panes.contains(&("\" · %".to_owned(), "Split below · right")));
        assert!(panes.contains(&("←↓↑→ · o".to_owned(), "Focus · next pane")));
        assert!(panes.contains(&("Shift-←↓↑→".to_owned(), "Resize")));
        assert!(panes.contains(&("x · z".to_owned(), "Close · zoom")));
    }

    #[test]
    fn pane_commands_follow_the_prefix() {
        type Case = (KeyCode, KeyModifiers, fn(&Action) -> bool);
        let cases: [Case; 12] = [
            (KeyCode::Char('"'), KeyModifiers::SHIFT, |a| {
                matches!(a, Action::SplitPane(Split::Horizontal))
            }),
            (KeyCode::Char('-'), KeyModifiers::NONE, |a| {
                matches!(a, Action::SplitPane(Split::Horizontal))
            }),
            (KeyCode::Char('%'), KeyModifiers::SHIFT, |a| {
                matches!(a, Action::SplitPane(Split::Vertical))
            }),
            (KeyCode::Char('|'), KeyModifiers::SHIFT, |a| {
                matches!(a, Action::SplitPane(Split::Vertical))
            }),
            (KeyCode::Char('S'), KeyModifiers::SHIFT, |a| {
                matches!(a, Action::SplitPaneHost)
            }),
            (KeyCode::Left, KeyModifiers::NONE, |a| {
                matches!(a, Action::FocusPane(Dir::Left))
            }),
            (KeyCode::Down, KeyModifiers::NONE, |a| {
                matches!(a, Action::FocusPane(Dir::Down))
            }),
            (KeyCode::Right, KeyModifiers::SHIFT, |a| {
                matches!(a, Action::ResizePane(Dir::Right))
            }),
            (KeyCode::Up, KeyModifiers::SHIFT, |a| {
                matches!(a, Action::ResizePane(Dir::Up))
            }),
            (KeyCode::Char('x'), KeyModifiers::NONE, |a| {
                matches!(a, Action::ClosePane)
            }),
            (KeyCode::Char('z'), KeyModifiers::NONE, |a| {
                matches!(a, Action::ZoomPane)
            }),
            (KeyCode::Char('o'), KeyModifiers::NONE, |a| {
                matches!(a, Action::NextPane)
            }),
        ];
        for (code, m, expected) in cases {
            let action = map(code, m, Focus::Terminal, true);
            assert!(
                action.as_ref().is_some_and(expected),
                "{code:?}: {action:?}"
            );
            // Without the prefix, the same keys go to the remote program.
            let plain = map(code, m, Focus::Terminal, false);
            assert!(matches!(plain, Some(Action::TerminalKey(_))), "{code:?}");
        }
        // `h` and `l` keep their meaning (home, logs).
        assert!(matches!(
            map(
                KeyCode::Char('h'),
                KeyModifiers::NONE,
                Focus::Terminal,
                true
            ),
            Some(Action::GoHome)
        ));
        // Vim-style moves, as documented: no conflict once home and logs move.
        let (map, ignored) = overrides(&[
            ("prefix.home", "0"),
            ("prefix.debug", "g"),
            ("prefix.pane_left", "h"),
            ("prefix.pane_down", "j"),
            ("prefix.pane_up", "k"),
            ("prefix.pane_right", "l"),
        ]);
        assert!(ignored.is_empty(), "{ignored:?}");
        assert_eq!(
            map.joined(&[
                "prefix.pane_left",
                "prefix.pane_down",
                "prefix.pane_up",
                "prefix.pane_right"
            ]),
            "hjkl"
        );
        let cx = KeyContext {
            prefix: true,
            ..cx(Focus::Terminal, None, false, true, &map)
        };
        assert!(matches!(
            map_key(key(KeyCode::Char('l'), KeyModifiers::NONE), cx),
            Some(Action::FocusPane(Dir::Right))
        ));
    }

    #[test]
    fn picking_a_host_only_moves_searches_and_chooses() {
        let keymap = Keymap::defaults();
        let picking = |focus| KeyContext {
            picking: true,
            ..cx(focus, None, false, false, &keymap)
        };
        let at = |code, m, focus| map_key(key(code, m), picking(focus));
        assert!(matches!(
            at(KeyCode::Esc, KeyModifiers::NONE, Focus::Hosts),
            Some(Action::CancelPanePick)
        ));
        assert!(matches!(
            at(KeyCode::Esc, KeyModifiers::NONE, Focus::Search),
            Some(Action::CancelPanePick)
        ));
        assert!(matches!(
            at(KeyCode::Char('c'), KeyModifiers::CONTROL, Focus::Hosts),
            Some(Action::CancelPanePick)
        ));
        assert!(matches!(
            at(KeyCode::Enter, KeyModifiers::NONE, Focus::Hosts),
            Some(Action::Connect)
        ));
        assert!(matches!(
            at(KeyCode::Char('j'), KeyModifiers::NONE, Focus::Hosts),
            Some(Action::SelectNext)
        ));
        assert!(matches!(
            at(KeyCode::Char('/'), KeyModifiers::NONE, Focus::Hosts),
            Some(Action::FocusSearch)
        ));
        // Typing in the search field still types.
        assert!(matches!(
            at(KeyCode::Char('w'), KeyModifiers::NONE, Focus::Search),
            Some(Action::SearchInput('w'))
        ));
        // Everything else waits: no panel, no quit, no disconnect.
        for code in ['f', 'p', 'q', 'd', 'e', 't'] {
            assert!(
                at(KeyCode::Char(code), KeyModifiers::NONE, Focus::Hosts).is_none(),
                "{code}"
            );
        }
    }
}
